var QUESTOES_SISTEMA_FINANCEIRO_NACIONAL = [{"id":28337,"enunciado":"São consideradas instituições financeiras as pessoas jurídicas, públicas ou privadas, que tenham como atividade principal ou acessória a coleta, a intermediação ou a aplicação de recursos financeiros próprios ou de terceiros, em moeda nacional ou estrangeira, e a custódia de valor de propriedade de terceiros.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"Lei 4.595/64 — conceito de instituição financeira","ancora":"lei-4595-instituicao-financeira"},"E":{"topico":"Lei 4.595/64 — conceito de instituição financeira","ancora":"lei-4595-instituicao-financeira"}}},{"id":28363,"enunciado":"A CAIXA não pode emprestar sob garantia de penhor industrial e caução de títulos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"Caixas econômicas — operações vedadas","ancora":"caixas-economicas"},"E":{"topico":"Caixas econômicas — operações vedadas","ancora":"caixas-economicas"}}},{"id":28365,"enunciado":"As SCTVMs são supervisionadas pela CVM.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"SCTVM/SDTVM — supervisão","ancora":"sctvm-sdtvm"},"E":{"topico":"SCTVM/SDTVM — supervisão","ancora":"sctvm-sdtvm"}}},{"id":28369,"enunciado":"A constituição e o funcionamento das pessoas jurídicas que tenham como objeto principal de sua atividade a prática de operações de arrendamento mercantil, denominadas sociedades de arrendamento mercantil, dependem de autorização da CVM.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"Leasing — autorização de funcionamento","ancora":"leasing"},"E":{"topico":"Leasing — autorização de funcionamento","ancora":"leasing"}}},{"id":28372,"enunciado":"As sociedades corretoras de câmbio são supervisionadas pela CVM.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"Corretoras de câmbio — supervisão","ancora":"bancos-cambio"},"E":{"topico":"Corretoras de câmbio — supervisão","ancora":"bancos-cambio"}}},{"id":28488,"enunciado":"Os pagamentos sem utilização de papel-moeda (non-cash) são efetuados principalmente por meio de cheques, transferências de crédito, cartões de crédito e de débito e, também, por débitos diretos. Todas essas movimentações, quando cursadas no SFN, podem ser realizadas em moeda nacional, em dólares norte-americanos ou em euros.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"STR — transferências e meios de pagamento","ancora":"str-transferencia"},"E":{"topico":"STR — transferências e meios de pagamento","ancora":"str-transferencia"}}},{"id":28489,"enunciado":"O CMN é o órgão formulador da política da moeda e do crédito, devendo atuar, inclusive, no sentido de promover o aperfeiçoamento das instituições e dos instrumentos financeiros, com vistas à maior eficiência do sistema de pagamentos e de mobilização de recursos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"CMN — órgão formulador de política monetária","ancora":"cmn-competencias"},"E":{"topico":"CMN — órgão formulador de política monetária","ancora":"cmn-competencias"}}},{"id":28490,"enunciado":"O Banco Central do Brasil (BACEN) é o principal executor das orientações do CMN.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"BACEN — executor das orientações do CMN","ancora":"bacen-atribuicoes"},"E":{"topico":"BACEN — executor das orientações do CMN","ancora":"bacen-atribuicoes"}}},{"id":28491,"enunciado":"Entre as competências do CMN encontra-se a de definir a forma como o Banco do Brasil administrará as reservas vinculadas.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"CMN — competências sobre Banco do Brasil","ancora":"cmn-competencias"},"E":{"topico":"CMN — competências sobre Banco do Brasil","ancora":"cmn-competencias"}}},{"id":28492,"enunciado":"Entre as atribuições do BACEN estão a de estabelecer as condições para o exercício de quaisquer cargos de direção nas instituições financeiras, a de vigiar a interferência de outras empresas nos mercados financeiros e de capitais e a de controlar o fluxo de capitais estrangeiros no país.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"BACEN — atribuições específicas","ancora":"bacen-atribuicoes"},"E":{"topico":"BACEN — atribuições específicas","ancora":"bacen-atribuicoes"}}},{"id":28493,"enunciado":"O BACEN tem competência para regulamentar, autorizar o funcionamento e supervisionar os sistemas de compensação e de liquidação, atividades que, no caso de sistemas de liquidação de operações com valores mobiliários, exceto títulos públicos e privados emitidos por bancos, são compartilhadas com a Comissão de Valores Mobiliários.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"BACEN — sistemas de compensação e liquidação","ancora":"bacen-atribuicoes"},"E":{"topico":"BACEN — sistemas de compensação e liquidação","ancora":"bacen-atribuicoes"}}},{"id":28494,"enunciado":"O CMN é o principal órgão executor da política traçada pelo BACEN, cumprindo-lhe, também, autorizar o funcionamento e exercer a fiscalização das instituições financeiras, emitir moeda e executar os serviços do meio circulante.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"CMN x BACEN — papéis e competências","ancora":"cmn-competencias"},"E":{"topico":"CMN x BACEN — papéis e competências","ancora":"cmn-competencias"}}},{"id":28495,"enunciado":"É objetivo do COPOM implementar as políticas econômica e tributária do governo federal.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"COPOM — objetivo e metas de inflação","ancora":"copom-metas"},"E":{"topico":"COPOM — objetivo e metas de inflação","ancora":"copom-metas"}}},{"id":28496,"enunciado":"Desde a adoção da sistemática de metas para a inflação como diretriz de política monetária, as decisões do COPOM passaram a ter como objetivo cumprir as metas para a inflação definidas pelo CMN. Se as metas não forem atingidas, cabe ao presidente do BACEN divulgar, em carta aberta ao ministro da Fazenda, os motivos do descumprimento, bem como as providências e o prazo para retorno da taxa de inflação aos limites estabelecidos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"COPOM — sistemática de metas para a inflação","ancora":"copom-metas"},"E":{"topico":"COPOM — sistemática de metas para a inflação","ancora":"copom-metas"}}},{"id":28497,"enunciado":"Promover a expansão e o funcionamento eficiente e regular do mercado de ações e estimular as aplicações permanentes em ações do capital social das companhias abertas são funções da CVM.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"CVM — competências no mercado de ações","ancora":"cvm-competencias"},"E":{"topico":"CVM — competências no mercado de ações","ancora":"cvm-competencias"}}},{"id":28498,"enunciado":"Assegurar a observância de práticas comerciais eqüitativas no mercado de valores mobiliários e estimular a formação de poupança e sua aplicação em valores mobiliários são funções da CVM.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"CVM — práticas equitativas e formação de poupança","ancora":"cvm-competencias"},"E":{"topico":"CVM — práticas equitativas e formação de poupança","ancora":"cvm-competencias"}}},{"id":28499,"enunciado":"Bancos comerciais devem ser constituídos sob a forma de sociedade anônima e na sua denominação social deve constar a palavra \"Banco\".","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"Bancos comerciais — forma jurídica e denominação","ancora":"bancos-comerciais"},"E":{"topico":"Bancos comerciais — forma jurídica e denominação","ancora":"bancos-comerciais"}}},{"id":28500,"enunciado":"A captação de depósitos à vista, livremente movimentáveis, é atividade típica dos bancos comerciais.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"Bancos comerciais — captação de depósitos à vista","ancora":"bancos-comerciais"},"E":{"topico":"Bancos comerciais — captação de depósitos à vista","ancora":"bancos-comerciais"}}},{"id":28501,"enunciado":"Os bancos múltiplos com carteira comercial devem ser organizados sob a forma de sociedade anônima e podem captar depósitos à vista.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"Bancos múltiplos — carteira comercial e depósitos","ancora":"bancos-multiplos"},"E":{"topico":"Bancos múltiplos — carteira comercial e depósitos","ancora":"bancos-multiplos"}}},{"id":28502,"enunciado":"Na denominação social dos bancos múltiplos deve constar a expressão \"Banco Múltiplo\".","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"Bancos múltiplos — denominação social","ancora":"bancos-multiplos"},"E":{"topico":"Bancos múltiplos — denominação social","ancora":"bancos-multiplos"}}},{"id":28504,"enunciado":"As cooperativas de crédito podem conceder crédito a qualquer brasileiro maior de 21 anos de idade, por meio de desconto de títulos, empréstimos e financiamentos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"Cooperativas de crédito — concessão de crédito","ancora":"cooperativas-credito"},"E":{"topico":"Cooperativas de crédito — concessão de crédito","ancora":"cooperativas-credito"}}},{"id":28505,"enunciado":"Além de centralizar o recolhimento e a posterior aplicação de todos os recursos oriundos do FGTS, a CAIXA integra o Sistema Brasileiro de Poupança e Empréstimo (SBPE) e o Sistema Financeiro da Habitação (SFH).","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"Caixas econômicas — SBPE e SFH","ancora":"caixas-economicas"},"E":{"topico":"Caixas econômicas — SBPE e SFH","ancora":"caixas-economicas"}}},{"id":28506,"enunciado":"Após ter incorporado o Banco Nacional da Habilitação (BNH) e o papel de agente operador do Fundo de Garantia por Tempo de Serviço (FGTS), a CAIXA passou a centralizar todas as contas recolhedoras do FGTS existentes na rede bancária e a administrar a arrecadação desse fundo e o pagamento dos valores aos trabalhadores.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"Caixas econômicas — incorporação do BNH e FGTS","ancora":"caixas-economicas"},"E":{"topico":"Caixas econômicas — incorporação do BNH e FGTS","ancora":"caixas-economicas"}}},{"id":28507,"enunciado":"Os bancos de câmbio são instituições financeiras, mas não estão autorizados a receber depósitos em contas sem remuneração, não movimentáveis por cheque ou por meio eletrônico pelo titular, cujos recursos sejam destinados à realização das operações de câmbio e operações de crédito vinculadas às de câmbio.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"Bancos de câmbio — autorização e depósitos","ancora":"bancos-cambio"},"E":{"topico":"Bancos de câmbio — autorização e depósitos","ancora":"bancos-cambio"}}},{"id":28508,"enunciado":"Na denominação dos bancos de câmbio, deve constar a expressão \"Casa de Câmbio\".","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"Bancos de câmbio — denominação social","ancora":"bancos-cambio"},"E":{"topico":"Bancos de câmbio — denominação social","ancora":"bancos-cambio"}}},{"id":28509,"enunciado":"Financiamentos à exportação e à importação e adiantamentos sobre contratos de câmbio são exemplos de operações de câmbio e(ou) operações de crédito vinculadas às operações de câmbio.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"Bancos de câmbio — operações de câmbio e crédito","ancora":"bancos-cambio"},"E":{"topico":"Bancos de câmbio — operações de câmbio e crédito","ancora":"bancos-cambio"}}},{"id":28510,"enunciado":"O BACEN poderá cancelar a autorização para funcionamento da SDTVM e de suas dependências que, no prazo de trinta dias contados da sua concessão, não iniciarem suas atividades.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"SCTVM/SDTVM — cancelamento de autorização","ancora":"sctvm-sdtvm"},"E":{"topico":"SCTVM/SDTVM — cancelamento de autorização","ancora":"sctvm-sdtvm"}}},{"id":28511,"enunciado":"As SDTVM operam no mercado acionário, comprando, vendendo e distribuindo títulos e valores mobiliários, inclusive ouro financeiro, por conta de terceiros, entre outras atividades.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"SCTVM/SDTVM — atuação no mercado acionário","ancora":"sctvm-sdtvm"},"E":{"topico":"SCTVM/SDTVM — atuação no mercado acionário","ancora":"sctvm-sdtvm"}}},{"id":28512,"enunciado":"As SCTVM podem intermediar operações de câmbio; praticar operações no mercado de câmbio de taxas flutuantes; praticar operações de conta margem; realizar operações compromissadas.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"SCTVM/SDTVM — operações permitidas","ancora":"sctvm-sdtvm"},"E":{"topico":"SCTVM/SDTVM — operações permitidas","ancora":"sctvm-sdtvm"}}},{"id":28513,"enunciado":"Praticar operações de compra e venda de metais preciosos, no mercado físico, por conta própria e de terceiros, e operar em bolsas de mercadorias e de futuros, por conta própria e de terceiros, estão entre os objetivos das SCTVM.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"SCTVM/SDTVM — metais preciosos e futuros","ancora":"sctvm-sdtvm"},"E":{"topico":"SCTVM/SDTVM — metais preciosos e futuros","ancora":"sctvm-sdtvm"}}},{"id":28514,"enunciado":"A normatização, a concessão de autorização, o registro e a supervisão dos fundos de investimento, tanto das SCTVM quanto das SDTVM, são de competência do BACEN.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"SCTVM/SDTVM — competência de supervisão","ancora":"sctvm-sdtvm"},"E":{"topico":"SCTVM/SDTVM — competência de supervisão","ancora":"sctvm-sdtvm"}}},{"id":28515,"enunciado":"As sociedades corretoras de câmbio têm por objeto social, entre outras atribuições, a intermediação em operações de câmbio e a prática de operações no mercado de câmbio de taxas flutuantes.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"Corretoras de câmbio — objeto social","ancora":"bancos-cambio"},"E":{"topico":"Corretoras de câmbio — objeto social","ancora":"bancos-cambio"}}},{"id":28516,"enunciado":"Às sociedades de arrendamento mercantil é vedada a contratação de operações de arrendamento mercantil com o próprio fabricante do bem arrendado.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"Leasing — vedação ao fabricante","ancora":"leasing"},"E":{"topico":"Leasing — vedação ao fabricante","ancora":"leasing"}}},{"id":28517,"enunciado":"O BNDES é o órgão do Ministério do Planejamento, Orçamento e Gestão que tem como objetivo apoiar empreendimentos que contribuam para o desenvolvimento do país.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"BNDES — vinculação ministerial","ancora":"bndes"},"E":{"topico":"BNDES — vinculação ministerial","ancora":"bndes"}}},{"id":28518,"enunciado":"A parceria com instituições financeiras que têm agências estabelecidas em todo o país permite a disseminação do crédito, possibilitando maior acesso aos recursos do BNDES.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"BNDES — disseminação de crédito via agentes","ancora":"bndes"},"E":{"topico":"BNDES — disseminação de crédito via agentes","ancora":"bndes"}}},{"id":28519,"enunciado":"O BACEN tem procurado atuar no sentido de promover o desenvolvimento dos sistemas de pagamentos de varejo, visando, sobretudo, ganhos de eficiência relacionados, por exemplo, com o maior uso de instrumentos eletrônicos de pagamento, com a melhor utilização das redes de máquinas de atendimento automático (ATM) e de transferências de crédito a partir do ponto de venda (PDV), bem como com a maior integração entre os pertinentes sistemas de compensação e de liquidação.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"STR — sistemas de pagamentos de varejo","ancora":"str-transferencia"},"E":{"topico":"STR — sistemas de pagamentos de varejo","ancora":"str-transferencia"}}},{"id":28520,"enunciado":"Por disposição regulamentar, todas as transferências de fundos entre contas de reservas bancárias têm de ser feitas por intermédio do Sistema de Transferência de Reservas (STR), operado pelo BACEN.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"STR — transferências entre reservas bancárias","ancora":"str-transferencia"},"E":{"topico":"STR — transferências entre reservas bancárias","ancora":"str-transferencia"}}},{"id":28521,"enunciado":"Antes da existência desse cadastro, havia dificuldade em identificar contas de depósitos e ativos mantidos no SFN por pessoas físicas e jurídicas, o que dificultava investigações e ações destinadas a combater a criminalidade.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"CCS — identificação de contas","ancora":"ccs-cadastro"},"E":{"topico":"CCS — identificação de contas","ancora":"ccs-cadastro"}}},{"id":28522,"enunciado":"O CCS contém todos os dados de valor, de movimentação financeira e de saldos de contas e(ou) aplicações.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"CCS — dados de valor e saldos","ancora":"ccs-cadastro"},"E":{"topico":"CCS — dados de valor e saldos","ancora":"ccs-cadastro"}}},{"id":28632,"enunciado":"Há dois grandes grupos de entidades no SFN: o subsistema normativo, que trata da regulação e da fiscalização, e o subsistema operativo, que trata da intermediação, do suporte operacional e da administração.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"SFN — estrutura normativa e operativa","ancora":"sfn-estrutura-geral"},"E":{"topico":"SFN — estrutura normativa e operativa","ancora":"sfn-estrutura-geral"}}},{"id":28633,"enunciado":"O SFN atua na intermediação financeira, processo pelo qual os agentes que estão superavitários, com sobra de dinheiro, transferem esses recursos para aqueles que estejam deficitários, com falta de dinheiro.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"SFN — intermediação financeira","ancora":"sfn-estrutura-geral"},"E":{"topico":"SFN — intermediação financeira","ancora":"sfn-estrutura-geral"}}},{"id":28634,"enunciado":"O Banco Nacional de Desenvolvimento Econômico e Social (BNDES) é uma das principais entidades supervisoras do SFN.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"BNDES — papel no SFN","ancora":"bndes"},"E":{"topico":"BNDES — papel no SFN","ancora":"bndes"}}},{"id":28635,"enunciado":"Na sua mais recente composição, o CMN passou a ser integrado pelo ministro da Fazenda, como presidente do conselho, pelo ministro do Planejamento, Orçamento e Gestão e pelo presidente do Banco do Brasil.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"CMN — composição atual","ancora":"cmn-composicao"},"E":{"topico":"CMN — composição atual","ancora":"cmn-composicao"}}},{"id":28636,"enunciado":"Compete ao CMN fixar as diretrizes e normas da política cambial, inclusive quanto a compra e venda de ouro e quaisquer operações em direitos especiais de saque e em moeda estrangeira.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"CMN — política cambial","ancora":"cmn-competencias"},"E":{"topico":"CMN — política cambial","ancora":"cmn-competencias"}}},{"id":28637,"enunciado":"São regulamentadas por meio de resoluções as matérias aprovadas pelo CMN, normativo de caráter público, sempre divulgado no Diário Oficial da União (DOU) e na página de normativos do Banco Central do Brasil (BACEN).","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"CMN — resolução e publicação no DOU","ancora":"cmn-competencias"},"E":{"topico":"CMN — resolução e publicação no DOU","ancora":"cmn-competencias"}}},{"id":28638,"enunciado":"Apenas a partir de reuniões consideradas não-sigilosas do CMN são lavradas atas, cujo extrato é publicado no DOU.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"CMN — atas e sigilo","ancora":"cmn-composicao"},"E":{"topico":"CMN — atas e sigilo","ancora":"cmn-composicao"}}},{"id":28639,"enunciado":"O BACEN executa a política cambial definida pelo Ministério do Planejamento, Orçamento e Gestão, regulamentando o mercado de câmbio e autorizando as instituições que nele operam.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"BACEN — política cambial","ancora":"bacen-atribuicoes"},"E":{"topico":"BACEN — política cambial","ancora":"bacen-atribuicoes"}}},{"id":28640,"enunciado":"As instituições financeiras estrangeiras podem funcionar no país somente mediante prévia autorização do BACEN ou decreto do Poder Executivo.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"BACEN — autorização de IF estrangeiras","ancora":"bacen-atribuicoes"},"E":{"topico":"BACEN — autorização de IF estrangeiras","ancora":"bacen-atribuicoes"}}},{"id":28641,"enunciado":"Compete ao BACEN autorizar e fiscalizar o funcionamento das administradoras de cartão de crédito.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"BACEN — cartões de crédito","ancora":"bacen-atribuicoes"},"E":{"topico":"BACEN — cartões de crédito","ancora":"bacen-atribuicoes"}}},{"id":28642,"enunciado":"Compete ao COPOM avaliar o cenário macroeconômico e os principais riscos a ele associados, com base nos quais são tomadas as decisões de política monetária.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"COPOM — avaliação macroeconômica","ancora":"copom-metas"},"E":{"topico":"COPOM — avaliação macroeconômica","ancora":"copom-metas"}}},{"id":28643,"enunciado":"As atas das reuniões do COPOM são divulgadas quinze dias úteis após a sua realização.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"COPOM — divulgação de atas","ancora":"copom-metas"},"E":{"topico":"COPOM — divulgação de atas","ancora":"copom-metas"}}},{"id":28644,"enunciado":"O COPOM reúne-se ordinariamente doze vezes por ano e extraordinariamente sempre que necessário, por convocação de seu presidente.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"COPOM — reuniões ordinárias","ancora":"copom-metas"},"E":{"topico":"COPOM — reuniões ordinárias","ancora":"copom-metas"}}},{"id":28645,"enunciado":"Apesar de ser um órgão normativo do SFN, a CVM não tem poderes para disciplinar, normatizar e fiscalizar a atuação dos diversos integrantes do mercado de capitais.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"CVM — poder normativo e fiscalizatório","ancora":"cvm-competencias"},"E":{"topico":"CVM — poder normativo e fiscalizatório","ancora":"cvm-competencias"}}},{"id":28646,"enunciado":"Compete ao BACEN, e não à CVM a atribuição de apurar, julgar ou punir as irregularidades eventualmente cometidas no mercado de capitais.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"CVM — apuração de irregularidades","ancora":"cvm-competencias"},"E":{"topico":"CVM — apuração de irregularidades","ancora":"cvm-competencias"}}},{"id":28647,"enunciado":"A CVM compõe a estrutura do Conselho de Recursos do Sistema Financeiro Nacional (CRSFN).","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"CRSFN — composição","ancora":"crsfn"},"E":{"topico":"CRSFN — composição","ancora":"crsfn"}}},{"id":28648,"enunciado":"É atribuição do CRSFN julgar, em segunda e última instâncias administrativas, os recursos interpostos das decisões relativas às penalidades administrativas aplicadas pelo BACEN e relativas a infração à legislação de consórcios.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"CRSFN — julgamento em segunda instância","ancora":"crsfn"},"E":{"topico":"CRSFN — julgamento em segunda instância","ancora":"crsfn"}}},{"id":28649,"enunciado":"Compete ao CRSFN apreciar os recursos de ofício, dos órgãos e entidades competentes, contra decisões de arquivamento de processos que versem sobre penalidades por infrações à legislação cambial, de capitais estrangeiros e de crédito rural e industrial.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"CRSFN — recursos de ofício","ancora":"crsfn"},"E":{"topico":"CRSFN — recursos de ofício","ancora":"crsfn"}}},{"id":28650,"enunciado":"Não é atribuição do CRSFN julgar recursos interpostos das decisões relativas às penalidades administrativas aplicadas pela Secretaria de Comércio Exterior do Ministério do Desenvolvimento, Indústria e Comércio Exterior (MDIC).","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"CRSFN — atribuições e limitações","ancora":"crsfn"},"E":{"topico":"CRSFN — atribuições e limitações","ancora":"crsfn"}}},{"id":28651,"enunciado":"Foi alterado o modus operandi do SELIC, operado pelo BACEN, que passou a liquidar operações com títulos públicos federais em tempo real.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"SELIC — liquidação em tempo real","ancora":"selic-sistema"},"E":{"topico":"SELIC — liquidação em tempo real","ancora":"selic-sistema"}}},{"id":28652,"enunciado":"Nem todos os títulos dos quais o SELIC é depositário são escriturais, isto é, emitidos exclusivamente na forma eletrônica. Cerca de 30% desses títulos são emitidos em papel.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"SELIC — títulos escriturais e em papel","ancora":"selic-sistema"},"E":{"topico":"SELIC — títulos escriturais e em papel","ancora":"selic-sistema"}}},{"id":28653,"enunciado":"O SELIC é gerido pelo BACEN e é por ele operado em parceria com a Andima. Os seus centros operacionais (centro principal e centro de contingência) estão localizados na cidade de São Paulo.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"SELIC — gestão e operação","ancora":"selic-sistema"},"E":{"topico":"SELIC — gestão e operação","ancora":"selic-sistema"}}},{"id":28654,"enunciado":"A CETIP é depositária principalmente de títulos de renda fixa privados, títulos públicos estaduais e municipais e títulos representativos de dívidas de responsabilidade do Tesouro Nacional, de que são exemplos os títulos relacionados com empresas estatais extintas, com o Fundo de Compensação de Variação Salarial (FCVS), com o Programa de Garantia da Atividade Agropecuária (PROAGRO) e com a dívida agrária (TDA).","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"CETIP/B3 — títulos custodiados","ancora":"cetip-b3"},"E":{"topico":"CETIP/B3 — títulos custodiados","ancora":"cetip-b3"}}},{"id":28655,"enunciado":"Com poucas exceções, os títulos de renda fixa privados, títulos públicos estaduais e municipais e títulos representativos de dívidas de responsabilidade do Tesouro Nacional são emitidos escrituralmente, isto é, sob a forma de registros eletrônicos. Esses títulos emitidos em papel são fisicamente custodiados por bancos autorizados.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"CETIP/B3 — emissão escritural e custódia física","ancora":"cetip-b3"},"E":{"topico":"CETIP/B3 — emissão escritural e custódia física","ancora":"cetip-b3"}}},{"id":28656,"enunciado":"A CETIP utiliza a compensação bilateral, nas operações com títulos negociados no mercado secundário, e a liquidação bruta em tempo real, na liquidação das operações com derivativos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"CETIP/B3 — compensação bilateral e liquidação","ancora":"cetip-b3"},"E":{"topico":"CETIP/B3 — compensação bilateral e liquidação","ancora":"cetip-b3"}}},{"id":28657,"enunciado":"O sistema de previdência social brasileiro está fundamentado sobre a previdência social básica, oferecida pelo poder público, e sobre a previdência privada, de caráter complementar à previdência social.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"Previdência complementar — estrutura","ancora":"previdencia-complementar"},"E":{"topico":"Previdência complementar — estrutura","ancora":"previdencia-complementar"}}},{"id":28658,"enunciado":"O CNSP inclui representante do Ministério do Planejamento, Orçamento e Gestão.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"Resseguro — CNSP e regulação","ancora":"resseguro"},"E":{"topico":"Resseguro — CNSP e regulação","ancora":"resseguro"}}},{"id":28659,"enunciado":"As entidades abertas de previdência privada são constituídas unicamente sob a forma de sociedades anônimas e têm por objetivo instituir e operar planos de benefícios de caráter previdenciário concedidos em forma de renda continuada ou pagamento único, sendo acessíveis a qualquer pessoa física.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"Previdência complementar — entidades abertas","ancora":"previdencia-complementar"},"E":{"topico":"Previdência complementar — entidades abertas","ancora":"previdencia-complementar"}}},{"id":28660,"enunciado":"A atividade bancária é mais orientada por produto que por cliente, pois um mesmo cliente pode ser consumidor, concomitantemente, de diversos produtos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"Operações bancárias — orientação por produto/cliente","ancora":"operacoes-ativas-passivas"},"E":{"topico":"Operações bancárias — orientação por produto/cliente","ancora":"operacoes-ativas-passivas"}}},{"id":28661,"enunciado":"As principais operações passivas correspondem a empréstimos em conta corrente, crédito pessoal, desconto de títulos, adiantamento a depositante, cheque especial, capital de giro, repasse do BNDES, e operação de crédito rural.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"Operações bancárias — operações passivas","ancora":"operacoes-ativas-passivas"},"E":{"topico":"Operações bancárias — operações passivas","ancora":"operacoes-ativas-passivas"}}},{"id":28662,"enunciado":"Conta corrente, cobrança, arrecadação de tributos e folha de pagamento são exemplos de operações ativas.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"Operações bancárias — operações ativas","ancora":"operacoes-ativas-passivas"},"E":{"topico":"Operações bancárias — operações ativas","ancora":"operacoes-ativas-passivas"}}},{"id":28663,"enunciado":"Os valores depositados e mantidos em depósito por prazo inferior a um mês recebem remuneração correspondente aos dias de depósito e proporcionalmente àquela estabelecida para o mês..","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"Poupança — remuneração por prazo inferior a um mês","ancora":"poupanca"},"E":{"topico":"Poupança — remuneração por prazo inferior a um mês","ancora":"poupanca"}}},{"id":28664,"enunciado":"Os depósitos em cadernetas de poupança efetuados nos dias 29, 30 e 31 de determinado mês serão remunerados no dia 1.º do mês seguinte, aplicando-se o índice correspondente ao dia 1.º do mês de depósito.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"Poupança — datas de aniversário (dias 29, 30, 31)","ancora":"poupanca"},"E":{"topico":"Poupança — datas de aniversário (dias 29, 30, 31)","ancora":"poupanca"}}},{"id":28665,"enunciado":"O dinheiro depositado em caderneta de poupança somente poderá ser sacado depois de transcorrido prazo fixado por ocasião do depósito.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"Poupança — livre movimentação","ancora":"poupanca"},"E":{"topico":"Poupança — livre movimentação","ancora":"poupanca"}}},{"id":28666,"enunciado":"Os impostos a serem pagos nessas operações são: imposto sobre operações financeiras (IOF) e imposto sobre serviços (ISS).","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"Leasing — IOF e ISS","ancora":"leasing"},"E":{"topico":"Leasing — IOF e ISS","ancora":"leasing"}}},{"id":28667,"enunciado":"O contrato de leasing pode ser quitado antes do encerramento do prazo.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"Leasing — quitação antecipada","ancora":"leasing"},"E":{"topico":"Leasing — quitação antecipada","ancora":"leasing"}}},{"id":28668,"enunciado":"Ao final do contrato de leasing, o arrendatário tem as seguintes opções: comprar o bem por valor previamente contratado; renovar o contrato por um novo prazo, tendo como principal o valor residual; devolver o bem ao arrendador.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"Leasing — opções ao final do contrato","ancora":"leasing"},"E":{"topico":"Leasing — opções ao final do contrato","ancora":"leasing"}}},{"id":28669,"enunciado":"O BNDES é um órgão vinculado ao Ministério da Fazenda.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"BNDES — vinculação ao Ministério da Fazenda","ancora":"bndes"},"E":{"topico":"BNDES — vinculação ao Ministério da Fazenda","ancora":"bndes"}}},{"id":28670,"enunciado":"Atualmente, o BNDES não é um banco de desenvolvimento. É uma empresa pública federal, com personalidade jurídica de direito priv ado e patrimônio próprio.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"BNDES — natureza jurídica (empresa pública)","ancora":"bndes"},"E":{"topico":"BNDES — natureza jurídica (empresa pública)","ancora":"bndes"}}},{"id":28671,"enunciado":"Os bancos estaduais de desenvolvimento são constituídos sob a forma de sociedades anônimas, devendo adotar, obrigatória e privativamente, em sua denominação social, a expressão Banco de Desenvolvimento, seguida do nome do estado em que tenha sede.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"Bancos estaduais de desenvolvimento","ancora":"bancos-desenvolvimento"},"E":{"topico":"Bancos estaduais de desenvolvimento","ancora":"bancos-desenvolvimento"}}},{"id":85385,"enunciado":"As cooperativas de crédito se caracterizam por","opcoes":["atuação exclusiva no setor rural.","retenção obrigatória dos eventuais lucros auferidos com suas operações.","concessão de crédito a associados e ao público em geral, por meio de desconto de títulos, empréstimos e financiamentos.","captação, por meio de depósitos à vista e a prazo, somente de associados, de empréstimos, repasses e refinanciamentos de outras entidades financeiras e de doações.","captação, por meio de depósitos à vista e a prazo, de associados, de entidades de previdência complementar e de sociedades seguradoras."],"correta":3,"explicacao":"Gabarito: <strong>captação, por meio de depósitos à vista e a prazo, somente de associados, de empréstimos, repasses e refinanciamentos de outras entidades financeiras e de doações.</strong>.","banca":"FCC","ano":2011,"temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"A":{"topico":"Cooperativas de crédito — características","ancora":"cooperativas-credito"},"B":{"topico":"Cooperativas de crédito — características","ancora":"cooperativas-credito"},"C":{"topico":"Cooperativas de crédito — características","ancora":"cooperativas-credito"},"D":{"topico":"Cooperativas de crédito — características","ancora":"cooperativas-credito"},"E":{"topico":"Cooperativas de crédito — características","ancora":"cooperativas-credito"}}},{"id":85387,"enunciado":"Sobre operações de resseguro e retrocessão realizadas no País, a legislação brasileira em vigor prevê","opcoes":["a possibilidade de contratação de Ressegurador Eventual sediado em paraísos fiscais.","a possibilidade de contratação por meio de Ressegurador Local, Admitido ou Eventual.","que o Ressegurador Local seja controlado por instituição financeira.","que sejam contratadas exclusivamente por intermédio do IRB-Brasil Re (antigo Instituto de Resseguros do Brasil).","a dispensa, às companhias seguradoras nacionais, de repassar risco, ou parte dele, a um ressegurador."],"correta":1,"explicacao":"Gabarito: <strong>a possibilidade de contratação por meio de Ressegurador Local, Admitido ou Eventual.</strong>.","banca":"FCC","ano":2011,"temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"A":{"topico":"Resseguro e retrocessão","ancora":"resseguro"},"B":{"topico":"Resseguro e retrocessão","ancora":"resseguro"},"C":{"topico":"Resseguro e retrocessão","ancora":"resseguro"},"D":{"topico":"Resseguro e retrocessão","ancora":"resseguro"},"E":{"topico":"Resseguro e retrocessão","ancora":"resseguro"}}},{"id":85388,"enunciado":"As Entidades Abertas de Previdência Complementar caracterizam-se por","opcoes":["terem como órgão responsável a Superintendência Nacional de Previdência Complementar ? PREVIC.","não permitirem a portabilidade da provisão matemática de benefícios a conceder.","proporcionarem planos com benefício de renda por sobrevivência, renda por invalidez, pensão por morte, pecúlio por morte e pecúlio por invalidez.","aceitarem contratação de planos previdenciários exclusivamente de forma individual.","oferecerem planos destinados apenas a funcionários de uma empresa ou grupo de empresas."],"correta":2,"explicacao":"Gabarito: <strong>proporcionarem planos com benefício de renda por sobrevivência, renda por invalidez, pensão por morte, pecúlio por morte e pecúlio por invalidez.</strong>.","banca":"FCC","ano":2011,"temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"A":{"topico":"Entidades Abertas de Previdência Complementar","ancora":"previdencia-complementar"},"B":{"topico":"Entidades Abertas de Previdência Complementar","ancora":"previdencia-complementar"},"C":{"topico":"Entidades Abertas de Previdência Complementar","ancora":"previdencia-complementar"},"D":{"topico":"Entidades Abertas de Previdência Complementar","ancora":"previdencia-complementar"},"E":{"topico":"Entidades Abertas de Previdência Complementar","ancora":"previdencia-complementar"}}},{"id":85389,"enunciado":"Conforme a legislação em vigor, o arrendamento mercantil (leasing) é uma operação cujo contrato","opcoes":["não pode ser quitado antecipadamente.","determina que o arrendatário é o proprietário do bem.","tem o prazo mínimo de 180 dias, na modalidade denominada leasing operacional.","contempla apenas bens novos.","implica pagamento do Imposto Sobre Serviços (ISS)."],"correta":4,"explicacao":"Gabarito: <strong>implica pagamento do Imposto Sobre Serviços (ISS).</strong>.","banca":"FCC","ano":2011,"temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"A":{"topico":"Leasing — características e prazos","ancora":"leasing"},"B":{"topico":"Leasing — características e prazos","ancora":"leasing"},"C":{"topico":"Leasing — características e prazos","ancora":"leasing"},"D":{"topico":"Leasing — características e prazos","ancora":"leasing"},"E":{"topico":"Leasing — características e prazos","ancora":"leasing"}}},{"id":85390,"enunciado":"Sobre operações de crédito rural é correto afirmar:","opcoes":["Podem ser utilizadas por produtor rural, desde que pessoa física.","Não podem financiar atividades de comercialização da produção.","É necessária a apresentação de garantias para obtenção de financiamento.","Não estão sujeitas a Imposto sobre Operações de Crédito, Câmbio e Seguro, e sobre Operações relativas a Títulos e Valores Mobiliários - IOF.","Devem ser apresentados orçamento, plano ou projeto nas operações de desconto de Nota Promissória Rural."],"correta":2,"explicacao":"Gabarito: <strong>É necessária a apresentação de garantias para obtenção de financiamento.</strong>.","banca":"FCC","ano":2011,"temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"A":{"topico":"Crédito rural — características","ancora":"credito-rural"},"B":{"topico":"Crédito rural — características","ancora":"credito-rural"},"C":{"topico":"Crédito rural — características","ancora":"credito-rural"},"D":{"topico":"Crédito rural — características","ancora":"credito-rural"},"E":{"topico":"Crédito rural — características","ancora":"credito-rural"}}},{"id":85391,"enunciado":"O Banco Nacional de Desenvolvimento Econômico e Social ? BNDES financia investimentos de empresas por meio do Cartão BNDES, observando que","opcoes":["uma empresa pode ter até 4 cartões de bancos emissores diferentes e somar seus limites em uma única transação.","o faturamento bruto anual deve ser superior a R$ 90 milhões.","o limite de crédito mínimo deve ser de R$ 1 milhão por cartão, por banco emissor.","o prazo máximo de parcelamento deve ser de 36 meses.","as taxas de juros sejam pós-fixadas."],"correta":0,"explicacao":"Gabarito: <strong>uma empresa pode ter até 4 cartões de bancos emissores diferentes e somar seus limites em uma única transação.</strong>.","banca":"FCC","ano":2011,"temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"A":{"topico":"BNDES — Cartão BNDES","ancora":"bndes"},"B":{"topico":"BNDES — Cartão BNDES","ancora":"bndes"},"C":{"topico":"BNDES — Cartão BNDES","ancora":"bndes"},"D":{"topico":"BNDES — Cartão BNDES","ancora":"bndes"},"E":{"topico":"BNDES — Cartão BNDES","ancora":"bndes"}}},{"id":85392,"enunciado":"O produto financeiro denominado nota promissória comercial (commercial paper), no mercado doméstico, apresenta","opcoes":["baixo risco de liquidez, quando emitidas por instituição financeira.","ausência de risco de crédito, quando analisadas por agência de rating.","garantia por parte do respectivo banco mandatário.","elevado risco de mercado, quando emitidas por prazo superior a 360 dias.","obrigatoriedade de registro na Comissão de Valores Mobiliários."],"correta":4,"explicacao":"Gabarito: <strong>obrigatoriedade de registro na Comissão de Valores Mobiliários.</strong>.","banca":"FCC","ano":2011,"temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"A":{"topico":"Nota promissória comercial (commercial paper)","ancora":"nota-promissoria"},"B":{"topico":"Nota promissória comercial (commercial paper)","ancora":"nota-promissoria"},"C":{"topico":"Nota promissória comercial (commercial paper)","ancora":"nota-promissoria"},"D":{"topico":"Nota promissória comercial (commercial paper)","ancora":"nota-promissoria"},"E":{"topico":"Nota promissória comercial (commercial paper)","ancora":"nota-promissoria"}}},{"id":85398,"enunciado":"Para o lançador, quando uma opção de compra é exercida, representa","opcoes":["o direito de compra.","o compromisso de compra.","a obrigação de venda.","o direito de venda.","a possibilidade de repactuação com o titular."],"correta":2,"explicacao":"Gabarito: <strong>a obrigação de venda.</strong>.","banca":"FCC","ano":2011,"temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"A":{"topico":"Derivativos — opções de compra (lançador)","ancora":"derivativos"},"B":{"topico":"Derivativos — opções de compra (lançador)","ancora":"derivativos"},"C":{"topico":"Derivativos — opções de compra (lançador)","ancora":"derivativos"},"D":{"topico":"Derivativos — opções de compra (lançador)","ancora":"derivativos"},"E":{"topico":"Derivativos — opções de compra (lançador)","ancora":"derivativos"}}},{"id":85399,"enunciado":"Uma carta de fiança bancária, garantindo uma operação de crédito, implica","opcoes":["a impossibilidade de substituição do fiador.","a responsabilidade solidária e como principal pagador, no caso de renúncia do fiador ao benefício de ordem.","a contragarantia ser formalizada por instrumento público.","o impedimento de compartilhamento da obrigação.","a obrigatória cobertura integral da dívida."],"correta":1,"explicacao":"Gabarito: <strong>a responsabilidade solidária e como principal pagador, no caso de renúncia do fiador ao benefício de ordem.</strong>.","banca":"FCC","ano":2011,"temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"A":{"topico":"Carta de fiança bancária","ancora":"carta-fianca"},"B":{"topico":"Carta de fiança bancária","ancora":"carta-fianca"},"C":{"topico":"Carta de fiança bancária","ancora":"carta-fianca"},"D":{"topico":"Carta de fiança bancária","ancora":"carta-fianca"},"E":{"topico":"Carta de fiança bancária","ancora":"carta-fianca"}}},{"id":85400,"enunciado":"O Fundo Garantidor de Créditos (FGC): I. proporciona garantia a depósitos judiciais. II. cobre créditos de cada pessoa contra a mesma instituição associada, ou contra todas as instituições associadas do mesmo conglomerado, até o valor limite de R$ 70.000,00. III. tem o custeio da garantia prestada feito com recursos provenientes do Banco Central do Brasil. Está correto o que consta em","opcoes":["II e III, apenas.","I e III, apenas.","II, apenas.","I, apenas.","I, II e III."],"correta":2,"explicacao":"Gabarito: <strong>II, apenas.</strong>.","banca":"FCC","ano":2011,"temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"A":{"topico":"FGC — Fundo Garantidor de Créditos","ancora":"fgc-garantias"},"B":{"topico":"FGC — Fundo Garantidor de Créditos","ancora":"fgc-garantias"},"C":{"topico":"FGC — Fundo Garantidor de Créditos","ancora":"fgc-garantias"},"D":{"topico":"FGC — Fundo Garantidor de Créditos","ancora":"fgc-garantias"},"E":{"topico":"FGC — Fundo Garantidor de Créditos","ancora":"fgc-garantias"}}},{"id":85401,"enunciado":"Depósitos bancários, em espécie ou em cheques de viagem, de valores individuais não significativos, realizados de maneira que o total de cada depósito não seja elevado, mas que no conjunto se torne significativo, podem configurar indício de ocorrência de","opcoes":["crime contra a administração privada.","fraude cambial.","fraude contábil.","crime de lavagem de dinheiro.","fraude fiscal."],"correta":3,"explicacao":"Gabarito: <strong>crime de lavagem de dinheiro.</strong>.","banca":"FCC","ano":2011,"temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"A":{"topico":"Lavagem de dinheiro — indícios e tipologia","ancora":"lavagem-dinheiro-coaf"},"B":{"topico":"Lavagem de dinheiro — indícios e tipologia","ancora":"lavagem-dinheiro-coaf"},"C":{"topico":"Lavagem de dinheiro — indícios e tipologia","ancora":"lavagem-dinheiro-coaf"},"D":{"topico":"Lavagem de dinheiro — indícios e tipologia","ancora":"lavagem-dinheiro-coaf"},"E":{"topico":"Lavagem de dinheiro — indícios e tipologia","ancora":"lavagem-dinheiro-coaf"}}},{"id":85402,"enunciado":"O Sistema de Autorregulação Bancária da Federação Brasileira de Bancos (FEBRABAN) estabelece que","opcoes":["as normas do seu código se sobrepõem à legislação vigente, inclusive ao Código de Proteção e Defesa do Consumidor.","não será processada qualquer demanda e/ou reclamação de caráter individual.","todas as instituições integrantes do Sistema Financeiro Nacional podem solicitar para dele participar.","o monitoramento das condutas dos bancos será feito pelo Banco Central do Brasil.","as normas do seu código abrangem apenas determinados produtos e serviços ofertados pelas instituições signatárias."],"correta":1,"explicacao":"Gabarito: <strong>não será processada qualquer demanda e/ou reclamação de caráter individual.</strong>.","banca":"FCC","ano":2011,"temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"A":{"topico":"FEBRABAN — Sistema de Autorregulação Bancária","ancora":"febraban"},"B":{"topico":"FEBRABAN — Sistema de Autorregulação Bancária","ancora":"febraban"},"C":{"topico":"FEBRABAN — Sistema de Autorregulação Bancária","ancora":"febraban"},"D":{"topico":"FEBRABAN — Sistema de Autorregulação Bancária","ancora":"febraban"},"E":{"topico":"FEBRABAN — Sistema de Autorregulação Bancária","ancora":"febraban"}}},{"id":4240837,"enunciado":"O mercado a termo de ações representa um aperfeiçoamento do mercado futuro. Ele permite que ambos os participantes de uma transação revertam sua posição antes da data do vencimento.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2003,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"Derivativos — mercado a termo","ancora":"derivativos"},"E":{"topico":"Derivativos — mercado a termo","ancora":"derivativos"}}},{"id":4240838,"enunciado":"No mercado a termo, o investidor se compromete a comprar ou a vender uma determinada quantidade de uma ação-objeto, por um preço fixado dentro de um prazo preestabelecido. As operações contratadas poderão ser liquidadas no vencimento ou em data antecipada solicitada pelo comprador ou pelo vendedor ou em decorrência de acordo mútuo das partes.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2003,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"Derivativos — mercado a termo","ancora":"derivativos"},"E":{"topico":"Derivativos — mercado a termo","ancora":"derivativos"}}},{"id":4240839,"enunciado":"Como regra geral, quaisquer pagamentos ou recebimentos em moeda estrangeira podem ser realizados no mercado de câmbio. Grande parte dessas operações não necessita de autorização prévia do BACEN para a sua realização, pois já se encontra descrita e especificada nos regulamentos e normas vigentes - Consolidação das Normas Cambiais (CNC).","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2003,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"Câmbio — operações e autorização","ancora":"cambio-posicao"},"E":{"topico":"Câmbio — operações e autorização","ancora":"cambio-posicao"}}},{"id":4240840,"enunciado":"O Sistema de Informações do Banco Central (SISBACEN) é um sistema eletrônico de coleta, armazenagem e troca de informações que liga o BACEN aos agentes do sistema financeiro nacional. Visto ser facultativo o registro das operações de câmbio realizadas no país, o SISBACEN é o principal meio de que dispõe o BACEN para monitorar e fiscalizar o mercado.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2003,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"BACEN — atribuições e sistemas de informação","ancora":"bacen-atribuicoes"},"E":{"topico":"BACEN — atribuições e sistemas de informação","ancora":"bacen-atribuicoes"}}},{"id":4240841,"enunciado":"A posição de câmbio representa o resultado entre as operações de compra e venda de moeda estrangeira, acrescida ou diminuída da posição no dia anterior. Essas operações são realizadas pelos estabelecimentos que podem operar em câmbio, com exceção das agências de turismo e dos hotéis, os quais devem observar os limites estabelecidos pela regulamentação específica.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2003,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"Câmbio — posição de câmbio","ancora":"cambio-posicao"},"E":{"topico":"Câmbio — posição de câmbio","ancora":"cambio-posicao"}}},{"id":4240842,"enunciado":"As taxas de câmbio são livremente pactuadas entre as partes, cabendo lembrar que a disponibilidade da moeda em espécie implica maiores custos e riscos para o banco vendedor. É por essa razão que os cheques de viagem podem, geralmente, ser adquiridos a taxas menores.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2003,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"Câmbio — taxas livremente pactuadas","ancora":"cambio-posicao"},"E":{"topico":"Câmbio — taxas livremente pactuadas","ancora":"cambio-posicao"}}},{"id":4240843,"enunciado":"A unificação cambial feita pelo BACEN em janeiro de 1999 significou a junção do segmento livre com o segmento flutuante.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2003,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"Câmbio — unificação cambial 1999","ancora":"cambio-posicao"},"E":{"topico":"Câmbio — unificação cambial 1999","ancora":"cambio-posicao"}}},{"id":4240844,"enunciado":"O objetivo desses contratos é proporcionar recursos antecipados ao importador, de sorte a incrementar o comércio internacional.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2003,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"ACC e ACE — conceito e finalidade","ancora":"acc-ace"},"E":{"topico":"ACC e ACE — conceito e finalidade","ancora":"acc-ace"}}},{"id":4240845,"enunciado":"Os ACC podem ser utilizados como instrumentos de ganho financeiro pelo importador.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2003,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"ACC e ACE — uso pelo importador","ancora":"acc-ace"},"E":{"topico":"ACC e ACE — uso pelo importador","ancora":"acc-ace"}}},{"id":4240846,"enunciado":"Os ACC consistem unicamente na antecipação total dos reais equivalentes à quantia em moeda estrangeira comprada a termo de exportadores pelo banco.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2003,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"ACC e ACE — antecipação total","ancora":"acc-ace"},"E":{"topico":"ACC e ACE — antecipação total","ancora":"acc-ace"}}},{"id":4240847,"enunciado":"O valor adiantado poderá ser averbado no próprio contrato de câmbio, ou por meio de instrumento em separado que se integrará ao contrato.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2003,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"ACC e ACE — averbação no contrato de câmbio","ancora":"acc-ace"},"E":{"topico":"ACC e ACE — averbação no contrato de câmbio","ancora":"acc-ace"}}},{"id":4240848,"enunciado":"A primeira fase dos ACC ocorre quando a mercadoria já está pronta e embarcada, aproveitando-se o máximo possível a variação cambial.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2003,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"ACC e ACE — primeira e segunda fases","ancora":"acc-ace"},"E":{"topico":"ACC e ACE — primeira e segunda fases","ancora":"acc-ace"}}},{"id":4240849,"enunciado":"O objetivo principal dos bancos comerciais é proporcionar o suprimento oportuno e adequado de recursos necessários para a concessão de financiamento a curto e médio prazos ao comércio, à indústria, às empresas prestadoras de serviços e às pessoas físicas.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2003,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"Bancos comerciais — objetivo principal","ancora":"bancos-comerciais"},"E":{"topico":"Bancos comerciais — objetivo principal","ancora":"bancos-comerciais"}}},{"id":4240850,"enunciado":"As cooperativas de crédito atuam basicamente no setor primário da economia, permitindo melhor comercialização de produtos rurais e facilitando o escoamento das safras agrícolas para os centros consumidores. Destaca-se que os usuários finais dos créditos por elas concedidos são sempre os cooperados.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2003,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"Cooperativas de crédito — setor de atuação","ancora":"cooperativas-credito"},"E":{"topico":"Cooperativas de crédito — setor de atuação","ancora":"cooperativas-credito"}}},{"id":4240851,"enunciado":"As sociedades de arrendamento mercantil nasceram do reconhecimento de que o lucro de uma atividade produtiva pode advir da simples utilização do equipamento e não necessariamente de sua propriedade.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2003,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"Leasing — origem e conceito","ancora":"leasing"},"E":{"topico":"Leasing — origem e conceito","ancora":"leasing"}}},{"id":4240852,"enunciado":"As companhias hipotecárias podem captar depósitos a prazo com correção monetária, por meio de letras imobiliárias, e estabelecer convênios com bancos comerciais para funcionarem exclusivamente como agentes do Sistema Financeiro da Habitação.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2003,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"Companhias hipotecárias","ancora":"companhias-hipotecarias"},"E":{"topico":"Companhias hipotecárias","ancora":"companhias-hipotecarias"}}},{"id":4240853,"enunciado":"o cheque devolvido em razão de contra-ordem receberá o código 21, nos casos usuais, e o código 28, se a contra-ordem for motivada por furto ou por roubo.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2003,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"Cheques — códigos de devolução (contra-ordem)","ancora":"cheques-devolucao"},"E":{"topico":"Cheques — códigos de devolução (contra-ordem)","ancora":"cheques-devolucao"}}},{"id":4240854,"enunciado":"o cheque devolvido por erro formal de preenchimento receberá, na primeira apresentação, o código 31; se reapresentado e novamente devolvido pela mesma razão, receberá o código 41.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2003,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"Cheques — códigos de devolução (erro formal)","ancora":"cheques-devolucao"},"E":{"topico":"Cheques — códigos de devolução (erro formal)","ancora":"cheques-devolucao"}}},{"id":4240855,"enunciado":"o cheque devolvido por insuficiência de fundos receberá, na primeira apresentação, o código 20; se reapresentado e novamente devolvido pela mesma razão, receberá o código 22.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2003,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"Cheques — códigos de devolução (insuficiência)","ancora":"cheques-devolucao"},"E":{"topico":"Cheques — códigos de devolução (insuficiência)","ancora":"cheques-devolucao"}}},{"id":4240856,"enunciado":"o cheque cuja assinatura o banco entender divergente da do correntista dele emissor será devolvido e receberá o código 12.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2003,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"Cheques — códigos de devolução (assinatura)","ancora":"cheques-devolucao"},"E":{"topico":"Cheques — códigos de devolução (assinatura)","ancora":"cheques-devolucao"}}},{"id":4240857,"enunciado":"o cheque cuja conta-corrente já estiver encerrada será devolvido e receberá o código 16.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2003,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"Cheques — códigos de devolução (conta encerrada)","ancora":"cheques-devolucao"},"E":{"topico":"Cheques — códigos de devolução (conta encerrada)","ancora":"cheques-devolucao"}}},{"id":4240858,"enunciado":"Embora muito raramente, os derivativos são usados como trava de risco (hedge) relativa a variações de taxas de juros ou a oscilações de taxas cambiais.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2003,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"Derivativos — hedge e trava de risco","ancora":"derivativos"},"E":{"topico":"Derivativos — hedge e trava de risco","ancora":"derivativos"}}},{"id":4240859,"enunciado":"Derivativos são usados na gerência de direitos e obrigações resultantes dos ativos originais, na criação de novos instrumentos nos mercados de capitais e na obtenção ou eliminação de riscos associados com a propriedade de ativos, sem os custos de venda ou compra efetiva de tais ativos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2003,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"Derivativos — gerência de riscos","ancora":"derivativos"},"E":{"topico":"Derivativos — gerência de riscos","ancora":"derivativos"}}},{"id":4240860,"enunciado":"Em geral, fundos de investimento não podem utilizar parcela significativa de seus patrimônios em valores mobiliários; já os limites impostos com relação a derivativos são pouco restritivos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2003,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"Derivativos — uso em fundos de investimento","ancora":"derivativos"},"E":{"topico":"Derivativos — uso em fundos de investimento","ancora":"derivativos"}}},{"id":4240861,"enunciado":"Os principais tipos de derivativos são as opções (de compra ou venda), as operações futuras, as operações a termo e as trocas (swaps).","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2003,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"Derivativos — principais tipos","ancora":"derivativos"},"E":{"topico":"Derivativos — principais tipos","ancora":"derivativos"}}},{"id":4240862,"enunciado":"Os chamados derivativos de eletricidade, emitidos por órgãos ou entidades do setor público, podem ser adquiridos por instituições financeiras e demais instituições autorizadas pelo BACEN a funcionar. Para tanto, tais derivativos, na forma de certificados representativos de contratos mercantis de compra e venda a termo de energia elétrica, não podem ser emitidos por empresas incluídas no sistema brasileiro de privatização.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2003,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"Derivativos — certificados representativos","ancora":"derivativos"},"E":{"topico":"Derivativos — certificados representativos","ancora":"derivativos"}}},{"id":4240863,"enunciado":"No caso de inadimplemento ou mora nas obrigações contratuais garantidas mediante alienação fiduciária, o proprietário fiduciário ou credor poderá vender a coisa a terceiros, sem a exigência de leilão, de hasta pública, de avaliação prévia ou de qualquer outra medida judicial ou extrajudicial, independentemente da existência de disposição expressa em contrário prevista no contrato, devendo aplicar o preço da venda no pagamento de seu crédito e das despesas decorrentes e entregar ao devedor o saldo apurado, se houver.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2003,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"Operações bancárias — alienação fiduciária","ancora":"operacoes-ativas-passivas"},"E":{"topico":"Operações bancárias — alienação fiduciária","ancora":"operacoes-ativas-passivas"}}},{"id":4240864,"enunciado":"Se o bem alienado fiduciariamente não for encontrado ou não se achar na posse do devedor, o credor poderá requerer a conversão do pedido de busca e apreensão, nos mesmos autos, em ação penal, por crime de estelionato, na forma prevista no Código de Processo Penal.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2003,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"Operações bancárias — alienação fiduciária","ancora":"operacoes-ativas-passivas"},"E":{"topico":"Operações bancárias — alienação fiduciária","ancora":"operacoes-ativas-passivas"}}},{"id":4240865,"enunciado":"Grande parte das operações com contratos futuros é liquidada por diferença. Na prática, o que se negocia não são produtos, e sim, riscos de preços.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2003,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"Derivativos — contratos futuros liquidados por diferença","ancora":"derivativos"},"E":{"topico":"Derivativos — contratos futuros liquidados por diferença","ancora":"derivativos"}}},{"id":4240866,"enunciado":"Conta-analfabeto é um tipo especial de conta de depósito à vista que só pode ser aberta se o titular apresentar procurador, nomeado por procuração passada em cartório, com poderes específicos para abrir e movimentar a conta em nome do depositante analfabeto.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2003,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"Operações bancárias — conta corrente analfabeto","ancora":"operacoes-ativas-passivas"},"E":{"topico":"Operações bancárias — conta corrente analfabeto","ancora":"operacoes-ativas-passivas"}}},{"id":4240867,"enunciado":"A exemplo da pessoa jurídica, o cidadão, na condição de pessoa física, pode contratar leasing.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2003,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"Leasing — pessoa física como arrendatária","ancora":"leasing"},"E":{"topico":"Leasing — pessoa física como arrendatária","ancora":"leasing"}}},{"id":4240868,"enunciado":"Na caderneta de poupança, para efeito de contagem de juros e correção monetária, o depósito efetuado por meio de cheque, desde que este não seja devolvido, deve ser considerado a partir da data de liberação do cheque.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2003,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"Poupança — depósito via cheque e contagem de juros","ancora":"poupanca"},"E":{"topico":"Poupança — depósito via cheque e contagem de juros","ancora":"poupanca"}}},{"id":4240869,"enunciado":"Despesas tais como seguro, manutenção, registro de contrato, ISS e demais encargos que incidam sobre bens arrendados via contrato de leasing serão de responsabilidade do arrendatário ou do arrendador, a depender do que for pactuado no referido contrato.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2003,"tipo":"certo_errado","temas_relacionados":["sistema_financeiro_nacional"],"indicadores_teoria":{"C":{"topico":"Leasing — responsabilidade por despesas acessórias","ancora":"leasing"},"E":{"topico":"Leasing — responsabilidade por despesas acessórias","ancora":"leasing"}}}];
